# Generates compositions.go: Unicode 15.0's primary composites, the canonical
# decomposition pairs that canonical composition recombines. Needs Python 3.12
# (Unicode 15.0).
#
#   python3.12 testdata/gen_compositions.py compositions.go
import sys, unicodedata as u

if u.unidata_version != "15.0.0":
	sys.exit("needs Unicode 15.0.0 (Python 3.12); this Python has %s" % u.unidata_version)

pairs = []
for c in range(sys.maxunicode + 1):
	d = u.decomposition(chr(c))
	if not d or d.startswith("<"):
		continue
	parts = [int(x, 16) for x in d.split()]
	if len(parts) == 2 and u.normalize("NFC", chr(parts[0]) + chr(parts[1])) == chr(c):
		pairs.append((parts[0], parts[1], c))

lines = [
	"// Code generated by testdata/gen_compositions.py; DO NOT EDIT.",
	"",
	"package contenthash",
	"",
	"// compositions are Unicode 15.0's primary composites: each canonical",
	"// decomposition pair that canonical composition recombines, by full code",
	"// point. Hangul syllables are composed algorithmically instead.",
	"var compositions = map[[2]rune]rune{",
]
lines += ["\t{0x%04X, 0x%04X}: 0x%04X," % p for p in pairs]
lines.append("}")
with open(sys.argv[1], "w") as f:
	f.write("\n".join(lines) + "\n")
print(len(pairs), "pairs")
